  {var w=Fresh();w.EnsureOrganisationsG();var s=new StructureG{System=w.SystemId,Station=w.StationKey44,Corp="foreign",State="Online",PhysicalQ=true};w.Organisations.Structures.Add(s);Check(w.SetAclQ(s.Id,"Everyone","","Store",true)!="","Foreign ACL cannot be edited");s.AclQ.Add(new(){Kind="Everyone",Action="Store",Allow=true});s.AclQ.Add(new(){Kind="Pilot",Subject="player",Action="Store",Allow=false,Priority=1});Check(!w.AccessQ(s,"player","Store"),"Higher priority denial overrides public ACL");s.AclQ.Clear();s.HoldsQ["player"]=new(){Items=new(){{"ore",30}}};w.SealStructureSafetyQ(s,true);w.SealStructureSafetyQ(s,true);Check(w.SystemsQ.SafetyWraps.Count==1&&s.HoldsQ["player"].Items.Count==0,"Structure loss seals multi-owner custody once");Check(w.RecoverSafetyQ(w.SystemsQ.SafetyWraps.Single().Id)!="","Immature safety cannot be released");w=Reload(w);Check(w.SystemsQ.SafetyWraps.Single().Items["ore"]==30,"Safety inventory persists without duplication");}
