  {var w=Fresh();w.Player.SetCombatHull(FleetCatalog.Source("Rorqual").Id);w.Hangar["fuel"]=5;Check(w.TransferCapitalQ("fuel",2,"Fuel",true)==""&&w.Hangar["fuel"]==3&&w.ActiveCapitalHoldQ.Fuel["fuel"]==2,"Capital fuel hold uses actual stock");Check(w.TransferCapitalQ("fuel",9,"Fuel",true)!="","No negative capital inventory");w=Reload(w);Check(w.ActiveCapitalHoldQ.Fuel["fuel"]==2,"Capital hold custody persists");Check(w.TransferCapitalQ("fuel",2,"Fuel",false)==""&&w.Hangar["fuel"]==5,"Capital hold withdrawal conserves stock");}
  {var w=Fresh();w.Population.Enabled=true;w.EnsurePopulationC();w.SetEconomyQ(true);var factory=w.Population.Businesses.First(b=>b.Kind=="Factory");factory.Product="ammo";w.Population.Businesses.RemoveAll(b=>b.Id!=factory.Id);w.MarketOrders.RemoveAll(o=>o.BusinessC.Length>0);factory.Stock.Clear();w.TickEconomyQ();Check(w.SystemsQ.NpcJobs.Count==0&&w.SystemsQ.Shortages.Count>0,"NPC shortages prevent free factory output");var recipe=CatalogQ.Data.Activities.First(a=>a.Kind=="manufacturing"&&a.Outputs.Any(o=>CatalogQ.Item(o.Type)==factory.Product));var materials=recipe.Inputs.ToDictionary(i=>CatalogQ.Item(i.Type),i=>(decimal)i.Quantity);factory.IndustrySkillQ=5;foreach(var i in materials)factory.Stock[i.Key]=i.Value;w.SystemsQ.EconomyNext=w.Now;decimal wallet=factory.Wallet;w.TickEconomyQ();var job=w.SystemsQ.NpcJobs.Single();Check(factory.Wallet==wallet-5&&materials.All(i=>factory.Stock[i.Key]==0),"NPC source inputs and finite installation money consumed");w.SimulationUtc=job.Finish;w.TickEconomyQ();Check(job.State=="Delivered"&&factory.Stock[job.Product]>=job.Output,"Persisted NPC job produces declared output");var produced=factory.Stock[job.Product];w.TickEconomyQ();Check(factory.Stock[job.Product]==produced,"NPC delivery sealed once");}
